CREATE TEMP TABLE AVAILABLECOLORS (
      productId VARCHAR(50),
      availableColors VARCHAR(255)
);

INSERT INTO AVAILABLECOLORS (productId, availableColors)
SELECT productid,
       COALESCE(STRING_AGG(DISTINCT color, ',' ORDER BY color), '') AS availableColors
FROM productdetails
WHERE productid = #{productId}
GROUP BY productid;

CREATE TEMP TABLE AVAILABLESIZES (
    productId VARCHAR(50),
    availableSizes VARCHAR(255)
);

INSERT INTO AVAILABLESIZES (productId, availableSizes)
SELECT productid,
       COALESCE(STRING_AGG(DISTINCT size, ',' ORDER BY size), '') AS availableSizes
FROM productdetails
WHERE productid = #{productId}
GROUP BY productid;

CREATE TEMP TABLE ACTIVESIZES (
    productId VARCHAR(50),
    activeSizes VARCHAR(255)
);

INSERT INTO ACTIVESIZES (productId, activeSizes)
SELECT productid,
       COALESCE(STRING_AGG(DISTINCT size, ',' ORDER BY size), '') AS activeSizes
FROM productdetails
WHERE productid = #{productId}
  AND color = #{color}
GROUP BY productid;
